// ---- lib/timezone.ts ----
// Timezone helpers. "Today" is always computed from profiles.timezone, never UTC/server zone.

export function getBrowserTimeZone(): string {
  try {
    return Intl.DateTimeFormat().resolvedOptions().timeZone || "UTC";
  } catch {
    return "UTC";
  }
}

export function isValidTimeZone(tz: string): boolean {
  try {
    new Intl.DateTimeFormat("en-US", { timeZone: tz });
    return true;
  } catch {
    return false;
  }
}

/** 'YYYY-MM-DD' for the given instant as seen in `timeZone`. */
export function localDateString(timeZone: string, at: Date = new Date()): string {
  const parts = new Intl.DateTimeFormat("en-CA", {
    timeZone,
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
  }).formatToParts(at);
  const get = (t: string) => parts.find((p) => p.type === t)!.value;
  return `${get("year")}-${get("month")}-${get("day")}`;
}

/** Weekday (0=Sun..6=Sat) of a 'YYYY-MM-DD' calendar date. */
export function weekdayOf(dateStr: string): number {
  const [y, m, d] = dateStr.split("-").map(Number);
  return new Date(Date.UTC(y, m - 1, d)).getUTCDay();
}

/** Add whole days to a 'YYYY-MM-DD' date (calendar math, DST-safe). */
export function addDays(dateStr: string, n: number): string {
  const [y, m, d] = dateStr.split("-").map(Number);
  const dt = new Date(Date.UTC(y, m - 1, d + n));
  return dt.toISOString().slice(0, 10);
}

/** Weekday (0=Sun..6=Sat) of "now" in `timeZone`. */
export function weekdayInTimeZone(timeZone: string, at: Date = new Date()): number {
  return weekdayOf(localDateString(timeZone, at));
}

/** Hour (0-23) of "now" in `timeZone`. */
export function hourInTimeZone(timeZone: string, at: Date = new Date()): number {
  const h = new Intl.DateTimeFormat("en-US", { timeZone, hour: "numeric", hourCycle: "h23" }).format(at);
  return Number(h) % 24;
}

/** e.g. "Wednesday · November 4, 2026" for a 'YYYY-MM-DD' date. */
export function formatLongDate(dateStr: string): string {
  const [y, m, d] = dateStr.split("-").map(Number);
  const dt = new Date(Date.UTC(y, m - 1, d));
  const weekday = new Intl.DateTimeFormat("en-US", { weekday: "long", timeZone: "UTC" }).format(dt);
  const rest = new Intl.DateTimeFormat("en-US", { month: "long", day: "numeric", year: "numeric", timeZone: "UTC" }).format(dt);
  return `${weekday} · ${rest}`;
}

// ---- lib/streaks/schedule.ts ----
/** A habit reduced to what streak math needs, with its live range in user-local dates. */
export type ScheduledHabit = {
  id: string;
  frequency_type: Habit["frequency_type"];
  active_days: number[] | null;
  /** first user-local day the habit counts (creation day) */
  firstDay: string;
  /** user-local day it stopped counting (archive day, exclusive) or null while active */
  endDay: string | null;
};

/** Completed (habit, day) pairs. Build keys with completionKey(). */
export type DoneSet = Set<string>;

export const completionKey = (habitId: string, day: string) => `${habitId}|${day}`;

export function toScheduled(habits: Habit[], timeZone: string): ScheduledHabit[] {
  return habits.map((h) => ({
    id: h.id,
    frequency_type: h.frequency_type,
    active_days: h.active_days,
    firstDay: localDateString(timeZone, new Date(h.created_at)),
    endDay: h.archived_at ? localDateString(timeZone, new Date(h.archived_at)) : null,
  }));
}

/** Is the habit required on this user-local day (live that day AND scheduled for its weekday)? */
export function isScheduledOn(h: ScheduledHabit, day: string): boolean {
  if (day < h.firstDay) return false;
  if (h.endDay !== null && day >= h.endDay) return false;
  return h.frequency_type === "daily" || (h.active_days ?? []).includes(weekdayOf(day));
}

/** First day of the user's week containing `day` (weeks start on `weekStart`, 0=Sun..6=Sat). */
export function weekStartOf(day: string, weekStart: number): string {
  const back = (weekdayOf(day) - weekStart + 7) % 7;
  const [y, m, d] = day.split("-").map(Number);
  return new Date(Date.UTC(y, m - 1, d - back)).toISOString().slice(0, 10);
}

// ---- lib/streaks/daily.ts ----
/**
 * Daily UVU: consecutive days on which EVERY daily habit was completed.
 * Returns null when the user has no (unarchived) daily habit: the streak doesn't exist then.
 *
 * Rules:
 *  - Walk back from today. Today only extends the streak once complete; an unfinished today
 *    never breaks it (end of day is sharp, but it can still be done until 23:59 local).
 *  - A past day with an unmet daily habit ends the streak, as does a day with no daily
 *    habit scheduled at all (before any existed).
 */
/** True when at least one daily habit is scheduled on `day` and every one of them is done. */
export function isDailyDayComplete(habits: ScheduledHabit[], done: DoneSet, day: string): boolean {
  const required = habits.filter((h) => h.frequency_type === "daily" && isScheduledOn(h, day));
  return required.length > 0 && required.every((h) => done.has(completionKey(h.id, day)));
}

export function computeDailyStreak(habits: ScheduledHabit[], done: DoneSet, today: string): number | null {
  const daily = habits.filter((h) => h.frequency_type === "daily");
  if (!daily.some((h) => h.endDay === null)) return null;

  const earliest = daily.reduce((min, h) => (h.firstDay < min ? h.firstDay : min), today);
  const dayStatus = (day: string) => isDailyDayComplete(daily, done, day);

  let streak = 0;
  let day = today;
  if (dayStatus(day)) streak++;
  day = addDays(day, -1);

  while (day >= earliest && dayStatus(day)) {
    streak++;
    day = addDays(day, -1);
  }
  return streak;
}

// ---- lib/streaks/weekly.ts ----
type Instance = { habitId: string; day: string };

function instancesInWeek(habits: ScheduledHabit[], weekStart: string): Instance[] {
  const out: Instance[] = [];
  for (let i = 0; i < 7; i++) {
    const day = addDays(weekStart, i);
    for (const h of habits) if (isScheduledOn(h, day)) out.push({ habitId: h.id, day });
  }
  return out;
}

/** True when every required instance in the user's current week is done (so the week counts now). */
export function isCurrentWeekComplete(habits: ScheduledHabit[], done: DoneSet, today: string, weekStart: number): boolean {
  const inst = instancesInWeek(habits, weekStartOf(today, weekStart));
  return inst.length > 0 && inst.every((i) => done.has(completionKey(i.habitId, i.day)));
}

/**
 * Weekly UVU: consecutive weeks in which every required instance of every habit (daily and
 * specific-days) was completed. Weeks run from `weekStart` (weekday of signup).
 *
 *  - Current week: if any required instance on a day BEFORE today is missing, the streak is 0
 *    (it breaks the moment an instance is missed). Otherwise the week counts once all its
 *    instances are done, and while still in progress it neither counts nor breaks.
 *  - Past weeks: all instances must be done; a week with no instances (before any habit
 *    existed) ends the walk.
 */
export function computeWeeklyStreak(habits: ScheduledHabit[], done: DoneSet, today: string, weekStart: number): number {
  if (habits.length === 0) return 0;
  const earliest = habits.reduce((min, h) => (h.firstDay < min ? h.firstDay : min), today);
  const isDone = (i: Instance) => done.has(completionKey(i.habitId, i.day));

  const currentStart = weekStartOf(today, weekStart);
  const current = instancesInWeek(habits, currentStart);
  if (current.some((i) => i.day < today && !isDone(i))) return 0;

  let streak = current.length > 0 && current.every(isDone) ? 1 : 0;

  let start = addDays(currentStart, -7);
  while (addDays(start, 6) >= earliest) {
    const inst = instancesInWeek(habits, start);
    if (inst.length === 0 || !inst.every(isDone)) break;
    streak++;
    start = addDays(start, -7);
  }
  return streak;
}

// ---- lib/streaks/broken.ts ----
/** Habits that were required on `day` but have no completion. */
export function missedOn(habits: ScheduledHabit[], done: DoneSet, day: string): ScheduledHabit[] {
  return habits.filter((h) => isScheduledOn(h, day) && !done.has(completionKey(h.id, day)));
}

/**
 * Should the user get a "streak broken" push for `missedDay` (the day that just ended)?
 * Only when a streak that was alive at the end of the previous day was actually lost, so people
 * with nothing to lose aren't pinged:
 *  - Daily UVU: the previous day was fully done AND a daily habit was missed on `missedDay`.
 *  - Weekly UVU: it was above 0 at the end of the previous day AND anything was missed on `missedDay`.
 */
export function streakBrokenOn(habits: ScheduledHabit[], done: DoneSet, missedDay: string, weekStart: number): boolean {
  const missed = missedOn(habits, done, missedDay);
  if (missed.length === 0) return false;

  const before = addDays(missedDay, -1);
  const dailyLost = missed.some((h) => h.frequency_type === "daily") && isDailyDayComplete(habits, done, before);
  const weeklyLost = computeWeeklyStreak(habits, done, before, weekStart) > 0;
  return dailyLost || weeklyLost;
}

// ---- lib/streaks/milestones.ts ----
/** Daily UVU milestones: 7, 30, then every +30 (60, 90, 120, ...). */
export function isDailyMilestone(n: number): boolean {
  return n === 7 || (n >= 30 && n % 30 === 0);
}

/** Weekly UVU milestones: every +4 weeks (4, 8, 12, ...). */
export function isWeeklyMilestone(n: number): boolean {
  return n >= 4 && n % 4 === 0;
}

export function milestoneMessage(kind: "daily" | "weekly", n: number): string {
  return `🔥 ${n}-${kind === "daily" ? "day" : "week"} UVU! Keep it going.`;
}

export const STREAK_BROKEN_MESSAGE = "You missed a habit today — your UVU is reset. Ready to start again tomorrow?";
